<?php require __DIR__ . '/includes/config.php'; require_login(); $items=cart_items($pdo);if(!$items)redirect('cart.php');$total=cart_total($items);if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO orders (user_id,customer_name,email,phone,address,payment_method,total) VALUES (?,?,?,?,?,?,?)');$s->execute([$_SESSION['user']['id'],trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['address']),$_POST['payment_method'],$total]);$orderId=(int)$pdo->lastInsertId();$i=$pdo->prepare('INSERT INTO order_items (order_id,product_id,name,price,quantity) VALUES (?,?,?,?,?)');foreach($items as $item)$i->execute([$orderId,$item['id'],$item['name'],$item['price'],$item['quantity']]);$_SESSION['cart']=[];flash('success','Order #' . $orderId . ' placed successfully.');redirect('orders.php');}$pageTitle='Checkout';require __DIR__ . '/includes/header.php'; ?><section class="container py-5"><div class="eyebrow">Almost there</div><h1 class="display-5 mb-4">Checkout</h1><form method="post" class="row g-4"><div class="col-lg-7"><div class="panel"><h2 class="h4 mb-4">Delivery details</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name</label><input required name="name" class="form-control" value="<?= e($_SESSION['user']['name']) ?>"></div><div class="col-md-6"><label class="form-label">Email</label><input required type="email" name="email" class="form-control" value="<?= e($_SESSION['user']['email']) ?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input required name="phone" class="form-control"></div><div class="col-12"><label class="form-label">Address</label><textarea required name="address" class="form-control" rows="3"></textarea></div></div><h2 class="h4 mt-5 mb-3">Payment</h2><div class="d-grid gap-2"><label class="panel"><input required type="radio" name="payment_method" value="bkash"> <strong>bKash</strong><span class="text-secondary ms-2">Mobile payment</span></label><label class="panel"><input type="radio" name="payment_method" value="nagad"> <strong>Nagad</strong><span class="text-secondary ms-2">Mobile payment</span></label><label class="panel"><input type="radio" name="payment_method" value="rocket"> <strong>Rocket</strong><span class="text-secondary ms-2">Mobile payment</span></label></div></div></div><div class="col-lg-5"><div class="panel"><h2 class="h4">Order summary</h2><?php foreach($items as $item): ?><div class="d-flex justify-content-between py-2"><span><?= e($item['name']) ?> × <?= $item['quantity'] ?></span><span>$<?= number_format($item['price']*$item['quantity'],2) ?></span></div><?php endforeach; ?><hr><div class="d-flex justify-content-between"><strong>Total</strong><strong>$<?= number_format($total,2) ?></strong></div><button class="btn btn-accent w-100 mt-4">Place order</button></div></div></form></section><?php require __DIR__ . '/includes/footer.php'; ?>